import React from 'react';
function Education() {
    return (  
       <div className='container'>
        <div className='row'>
            <div className='col-6'>
                <img src='media/images/images/education.svg'></img>
            </div>
            <div className='col-6'>
                <h1 mb-5>Free and open market education</h1>
                <p>Varsity, the largest online stock market education book in the world<br/>
                Covering everything from the basucs to advanced trading.</p>
           <a href=''>Versity <i class="fa fa-arrow-right" aria-hidden="true"></i></a>
           
           <p>Trading Q&A, the most active trading and investment community  in <br/>
           india for all ypur market related queries.</p>

           <a href=''>Trading Q&A <i class="fa fa-arrow-right" aria-hidden="true"></i></a>
            </div>
        </div>
       </div>
    );
}

export default Education;
